#include "power_weight_transaction.h"
#define main unused_weight_transaction_service_fixture_main
#include "power_weights_service_test.cpp"
#undef main
namespace {
struct TransactionFake {
 WeightFake weights;std::optional<PowerWeightReceipt> durable;bool active=false,offline=false;
 unsigned persists=0,writes=0,restarts=0,verifies=0;int fail_persist=0,fail_write=0;
 PowerWeightBoundaryResult restart_status{true,false,false,false,false,"refreshed"},verify_status{true,false,false,false,false,"verified"};
 explicit TransactionFake(bool alternate=false):weights(alternate){weights.current.registry=PowerWeightRegistrySnapshot{{L"EnableGpuFirmware",4,{0x11,0,0,0}}};}
 PowerWeightReceipt receipt(){return make_weight_receipt(weights.current,{{0,1.25,4096},{31,0,6144}});}
 PowerWeightTransactionApi api(){PowerWeightTransactionApi a;
  a.capture=[this](dc_gpu* gpu,bool registry){if(offline)throw VoltageEquationEvidenceError("Driver unavailable",VoltagePolicyAvailability::unsupported);auto c=weights.api().capture(gpu,registry);c.target.handle+=weights.reads;c.adapter.nvapi_handle=c.target.handle;return c;};
  a.recovery_registry=[this](const PowerWeightReceipt&){return PowerWeightRegistryRecovery{*weights.current.windows,*weights.current.registry};};
  a.persist=[this](const PowerWeightReceipt& r,bool create){++persists;if(static_cast<int>(persists)==fail_persist)throw std::runtime_error("Journal write failed");if(create){weight_check(!active||durable->id==r.id,"Create may only publish current selected receipt");active=true;}else weight_check(active&&durable&&durable->id==r.id,"Progress requires matching active receipt");durable=decode_weight_receipt(encode_weight_receipt(r));};
  a.clear_active=[this](const PowerWeightReceipt& r){weight_check(durable&&durable->id==r.id&&durable->phase=="removed"&&!durable->uncertain,"Clear only after durable original verification");active=false;return true;};
  a.write=[this](const VoltageScaffoldWindowsTarget& t,const PowerWeightRegistrySnapshot& expected,const PowerWeightRegistrySnapshot& desired,const std::function<bool(const std::wstring&,std::string&)>& journal){PowerWeightRegistryWriteApi writer;
   writer.read=[this](const std::wstring&){return *weights.current.registry;};writer.write=[this](const std::wstring&,const std::wstring& name,const std::optional<PowerWeightRegistryValue>& value,std::string& error){weight_check(active&&durable&&std::find(durable->issued_names.begin(),durable->issued_names.end(),name)!=durable->issued_names.end(),"Durable cumulative issued-name journal precedes every effect");++writes;auto& current=*weights.current.registry;auto found=std::find_if(current.begin(),current.end(),[&](const auto& v){return v.name==name;});if(value){if(found==current.end())current.push_back(*value);else *found=*value;}else if(found!=current.end())current.erase(found);if(static_cast<int>(writes)==fail_write){error="Accepted registry effect reported failure";return false;}return true;};return write_power_weight_registry(t,expected,desired,journal,writer);};
  a.restart=[this](const VoltageScaffoldWindowsTarget& target){weight_check(durable&&durable->refresh_requested&&durable->uncertain&&durable->windows.instance_id==target.instance_id,"Refresh intent persisted before selected refresh");++restarts;if(restart_status.ok&&!restart_status.reboot_required&&!restart_status.timed_out&&!restart_status.cleanup_pending&&!restart_status.uncertain){const auto derived=derive_weight_receipt(*durable);weights.current.image=durable->restoring?durable->image:*derived.plan.expected_image;weights.current.info=durable->restoring?durable->info:*derived.plan.expected_info;offline=false;}return restart_status;};
  a.fresh_verify=[this](const PowerWeightReceipt& r,bool original){++verifies;if(!verify_status.ok||verify_status.reboot_required||verify_status.timed_out||verify_status.cleanup_pending||verify_status.uncertain)return verify_status;const auto derived=derive_weight_receipt(r);const auto checked=verify_power_relationship_weights(derived.plan,weights.current.identity,weights.current.layout,weights.current.info,&weights.current.image,original);return PowerWeightBoundaryResult{checked.ok,false,false,false,false,checked.message};};return a;
 }
};
void transaction_tests(){for(bool alternate:{false,true}){TransactionFake f(alternate);const auto saved=f.receipt();PowerWeightTransaction transaction(f.api(),reinterpret_cast<dc_gpu*>(1),f.weights.current.adapter);weight_check(f.persists==0&&f.weights.reads==0,"Transaction construction performs no I/O");const auto applied=transaction.run(PowerWeightOperation::apply,saved);if(!applied.ok)std::fprintf(stderr,"Apply: %s\n",applied.message.c_str());weight_check(applied.ok&&!applied.no_change&&f.writes==2&&f.restarts==1&&f.verifies==1&&f.active&&applied.receipt->phase=="active"&&!applied.receipt->uncertain,"Actual receipt/projector and narrow writer activate only after refresh plus complete proof");const auto removed=transaction.run(PowerWeightOperation::remove,*applied.receipt);if(!removed.ok)std::fprintf(stderr,"Remove: %s\n",removed.message.c_str());weight_check(removed.ok&&removed.receipt->restoring&&removed.receipt->phase=="removed"&&f.writes==4&&f.restarts==2&&f.verifies==2&&!f.active&&f.weights.current.image==saved.image&&f.weights.current.info==saved.info&&f.weights.current.registry->size()==1,"Three-way removal restores only owned names and verifies complete original image/INFO");}
 {TransactionFake f;auto saved=make_weight_receipt(f.weights.current,{{0,1,4096}});PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(result.ok&&result.no_change&&f.persists==0&&f.writes==0&&f.restarts==0,"No-op Apply creates no receipt/effects/refresh");}
 {TransactionFake f;auto saved=f.receipt();f.weights.current.info[0x5000]^=1;PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);weight_check(!transaction.run(PowerWeightOperation::apply,saved).ok&&f.persists==0&&f.writes==0,"Stale original INFO refuses before journaling/effects");}
 {TransactionFake f;auto saved=f.receipt();f.fail_persist=1;PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(!result.ok&&result.recovery_required&&f.writes==0&&f.restarts==0,"Failed initial journal prevents every effect and reports possible journal recovery");}
 {TransactionFake f;auto saved=f.receipt();f.fail_persist=4;PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(!result.ok&&result.may_have_changed&&result.recovery_required&&f.writes==1&&f.restarts==0&&result.receipt->issued_names.size()==1,"Failed second before-effect journal retains only issued prefix");f.fail_persist=0;auto removed=transaction.run(PowerWeightOperation::remove,*result.receipt);weight_check(removed.ok&&f.writes==2&&!f.active,"Explicit recovery removes issued prefix without touching unissued names");}
 {TransactionFake f;auto saved=f.receipt();f.fail_write=1;PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(!result.ok&&result.may_have_changed&&result.receipt->uncertain&&f.restarts==0,"Accepted-but-failed registry write retains discoverable uncertain receipt");f.fail_write=0;f.offline=true;auto removed=transaction.run(PowerWeightOperation::remove,*result.receipt);weight_check(removed.ok&&f.restarts==1&&!f.offline&&!f.active,"Disconnected removal uses independently bound registry recovery then fresh full original proof");}
 {TransactionFake f;auto saved=f.receipt();PowerWeightTransaction initial(f.api(),nullptr,f.weights.current.adapter);auto pending=initial.run(PowerWeightOperation::apply,saved);weight_check(pending.ok,"Recovery identity fixture activated");auto callbacks=f.api();auto capture=callbacks.capture;unsigned attempts=0;callbacks.capture=[&](dc_gpu* gpu,bool registry){if(!attempts++)throw VoltageEquationEvidenceError("First helper live capture transient",VoltagePolicyAvailability::transient);return capture(gpu,registry);};dc_gpu_identity absent{};PowerWeightTransaction recovering(callbacks,nullptr,absent);auto removed=recovering.run(PowerWeightOperation::remove,*pending.receipt);weight_check(removed.ok&&attempts>=2&&!f.active,"Removal with absent initial helper identity accepts later newly self-paired live capture after registry fallback");PowerWeightTransaction applying(f.api(),nullptr,absent);weight_check(!applying.run(PowerWeightOperation::apply,saved).ok,"Apply never relaxes absent opened identity");}
 {TransactionFake f;auto saved=f.receipt();f.restart_status={false,true,false,false,true,"Reboot required"};PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(!result.ok&&result.reboot_required&&result.recovery_required&&result.receipt->phase=="refresh_pending"&&f.verifies==0,"Reboot requirement is not activation success");}
 {TransactionFake f;auto saved=f.receipt();f.verify_status={false,false,true,false,true,"Fresh process timed out"};PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(!result.ok&&result.timed_out&&result.recovery_required&&result.receipt->phase=="verifying"&&f.active,"Fresh-process timeout retains staged recovery");f.verify_status={true,false,false,false,false,""};auto verified=transaction.run(PowerWeightOperation::verify,*result.receipt);weight_check(verified.ok&&verified.receipt->phase=="active"&&f.restarts==1,"Explicit Verify retries proof without registry write or refresh");f.restart_status={false,false,true,false,true,"Removal refresh timeout"};auto removed=transaction.run(PowerWeightOperation::remove,*verified.receipt);weight_check(!removed.ok&&removed.receipt->restoring&&removed.receipt->phase=="remove_refresh_pending","Failed removal preserves durable original verification direction");f.weights.current.image=saved.image;f.weights.current.info=saved.info;auto original=transaction.run(PowerWeightOperation::verify,*removed.receipt);weight_check(original.ok&&original.receipt->phase=="removed"&&!f.active,"Verify after removal failure uses original direction without message parsing");}
 {TransactionFake f;auto saved=f.receipt();PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto applied=transaction.run(PowerWeightOperation::apply,saved);f.weights.current.registry->back().bytes.back()^=1;const auto count=f.writes;auto removed=transaction.run(PowerWeightOperation::remove,*applied.receipt);weight_check(!removed.ok&&f.writes==count&&f.active,"Third-value owned-name conflict refuses removal without writes");}
 {TransactionFake f;auto saved=f.receipt();PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);auto applied=transaction.run(PowerWeightOperation::apply,saved);f.weights.current.registry->push_back({L"vbios",3,saved.image});const auto removed=transaction.run(PowerWeightOperation::remove,*applied.receipt);weight_check(removed.ok&&f.weights.current.registry->size()==2,"Removal preserves unrelated registry additions");}
 {TransactionFake f;auto saved=f.receipt();PowerWeightTransaction transaction(f.api(),nullptr,f.weights.current.adapter);f.weights.current.adapter.uuid[4]='X';auto result=transaction.run(PowerWeightOperation::apply,saved);weight_check(!result.ok&&f.writes==0&&f.persists==0,"Changed live UUID cannot use removal-only fallback during Apply");}
}
}
int main(){transaction_tests();std::printf("Power weight transaction: %u checks\n",weight_checks);return 0;}
